import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
def load(f,s=2): return pd.read_csv(f).iloc[::s].reset_index(drop=True)
def simQ(p,d,dt=0.002):
  Kp,Ki,Tq,Dq=p
  V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values;e=Vs-V-(Vs[0]-V[0])
  I=0;q=0;Q=[]
  for k in range(len(V)):
    u=Kp*e[k]+I; q+=dt*(u-q)/Tq;Q.append(q)
    I+=dt*Ki*(e[k]-Dq*u)
  return np.array(Q)
for f in ['train/A_fault_op1.csv','train/A_vref_op1.csv','train/A_gentrip_op1.csv']:
