import pandas as pd,numpy as np,glob
def arx(f,inputs,na=3,nb=3,s=5):
  d=pd.read_csv(f).iloc[::s].reset_index(drop=True)
  th=d.bus_angle_rad.values; w=np.r_[0,np.diff(th)]/(s*1e-3)/(2*np.pi*60)
  sig={'V':d.voltage_pu.values,'w':w,'th':th,'Vs':d.voltage_setpoint_pu.values,'P':d.active_power_pu.values}
  y=d.reactive_power_pu.values;n=len(y);L=max(na,nb)
  cols=[y[L-i:n-i] for i in range(1,na+1)]
  for k in inputs: cols+=[sig[k][L-i:n-i] for i in range(0,nb)]
  A=np.c_[np.array(cols).T,np.ones(n-L)];c,*_=np.linalg.lstsq(A,y[L:],rcond=None)
  # simulate
  return np.std(y[L:]-A@c)
for f in sorted(glob.glob('train/*.csv')):
